import { AxisScale } from '@visx/axis';
import { isNumber, isUndefined } from 'lodash-es';

import { getYScaleForTimeseries } from './scale.js';
import { getYScaleDomains } from './yScaleDomain.js';
import {
  MinScaleBoundary,
  MinMaxConfig,
  MaxScaleBoundary,
} from '../../core/types/min-max-config.js';
import { MinMax } from '../../core/types/min-max.js';
import { AxisScaleType } from '../../core/types/scales.js';
import { TimeseriesUnit } from '../../core/types/timeseries.js';
import { TimeseriesChartYAxisProps } from '../slots/YAxis.js';
import { YAxisScales } from '../types/state.js';
import { TimeseriesChartYAxisConfig } from '../types/timeseries-config.js';
import { ChartVariant } from '../types/timeseries-props.js';
import {
  WeakMapSeries,
  WeakMapDatapoints,
  TimeseriesPerVariant,
} from '../types/timeseries.js';

export interface ScaleMetadata {
  min?: number;
  max?: number;
  unit?: TimeseriesUnit;
}

/**
 * Finds the y-scale based on the series unit.
 *
 * @param seriesUnit -
 * @param yScales -
 * @returns
 */
export function getYScaleByUnit(
  seriesUnit: TimeseriesUnit,
  yScales: YAxisScales,
): AxisScale<number> {
  if (seriesUnit === yScales.left?.unit) {
    return yScales.left!.scale;
  }

  return yScales.right?.scale || yScales.left!.scale;
}

/**
 * Finds the y-scale type based on the series unit.
 *
 * @param seriesUnit -
 * @param yScales -
 * @param axisScaleType -
 * @returns
 */
export function getYScaleTypeByUnit(
  seriesUnit: TimeseriesUnit,
  yScales: YAxisScales,
  axisScaleType: TimeseriesChartYAxisConfig,
): AxisScaleType {
  if (seriesUnit === yScales.left?.unit) {
    return axisScaleType.left?.scale ?? 'linear';
  }

  return (axisScaleType.right?.scale || axisScaleType.left?.scale) ?? 'linear';
}

const getConfigMinMax = (
  yAxisConfig: TimeseriesChartYAxisProps | undefined,
): Partial<MinMaxConfig> | undefined => {
  if (!yAxisConfig) {
    return undefined;
  }

  return {
    min: yAxisConfig.min,
    max: yAxisConfig.max,
  };
};

const isDefaultValue = (
  value: MinScaleBoundary | MaxScaleBoundary | undefined,
) => isUndefined(value) || value === 'auto';

const isMissingData = (dataBoundaries: ScaleMetadata | undefined) =>
  isUndefined(dataBoundaries) ||
  isUndefined(dataBoundaries.min) ||
  isUndefined(dataBoundaries.max);

const isDefaultConfig = (configMinMax: Partial<MinMaxConfig> | undefined) =>
  isUndefined(configMinMax) ||
  (isDefaultValue(configMinMax.min) && isDefaultValue(configMinMax.max));

const isUserConfigured = (
  configMinMax: Partial<MinMaxConfig> | undefined,
): configMinMax is MinMaxConfig =>
  !isUndefined(configMinMax) &&
  isNumber(configMinMax.min) &&
  isNumber(configMinMax.max);

/**
 * When the user provides a partial configuration for an axis, meaning either
 * the min or the max, we'll try to provide a nice value for the non-provided
 * boundary.
 *
 * @param configMinMax - partial min/max config provided by the user
 * @param zeroBaselineDomainMin - min value provided to force 0 to be in chart
 * @param zeroBaselineDomainMax - max value provided to force 0 to be in chart
 * @param niceDomainMin - minimum provided by a nice scale
 * @param niceDomainMax - maximum provided by a nice scale
 */
function boundariesForPartialConfig(
  configMinMax: Partial<MinMaxConfig>,
  zeroBaselineDomainMin: number,
  zeroBaselineDomainMax: number,
  niceDomainMin: number,
  niceDomainMax: number,
): MinMax {
  let min =
    configMinMax?.min === 'data-min' ? niceDomainMin : zeroBaselineDomainMin;
  let max =
    configMinMax?.max === 'data-max' ? niceDomainMax : zeroBaselineDomainMax;

  if (isNumber(configMinMax?.min)) {
    min = configMinMax?.min;
  }
  if (isNumber(configMinMax?.max)) {
    max = configMinMax?.max;
  }

  return { min, max };
}

function getAutoScales(
  dataBoundaries: Required<ScaleMetadata>,
  zeroBaselineBoundaries: MinMax,
  height: number,
  scaleType: AxisScaleType,
) {
  const scale = getYScaleForTimeseries(dataBoundaries, height, scaleType);
  const zeroBaseLineScale = getYScaleForTimeseries(
    zeroBaselineBoundaries,
    height,
    scaleType,
  );

  return { scale, zeroBaseLineScale };
}

/**
 * Method to build a scale based on data-boundaries and configuration given by the
 * user, setting a nice scale for those values not configured.
 *
 * @param height - height of the chart
 * @param dataBoundaries -
 * @param configMinMax -
 * @param scaleType -
 */
const buildYScale = (
  height: number,
  dataBoundaries: Required<ScaleMetadata>,
  configMinMax: Partial<MinMaxConfig> | undefined,
  scaleType: AxisScaleType = 'linear',
) => {
  let scaleMin, scaleMax;
  const zeroBaselineDomainMin: number =
    dataBoundaries.min > 0 ? 0 : dataBoundaries.min;
  const zeroBaselineDomainMax: number =
    dataBoundaries.max < 0 ? 0 : dataBoundaries.max;

  if (isUserConfigured(configMinMax)) {
    scaleMin = configMinMax.min;
    scaleMax = configMinMax.max;
  } else if (isDefaultConfig(configMinMax)) {
    scaleMin = zeroBaselineDomainMin;
    scaleMax = zeroBaselineDomainMax;
  } else {
    const { scale, zeroBaseLineScale } = getAutoScales(
      dataBoundaries,
      { min: zeroBaselineDomainMin, max: zeroBaselineDomainMax },
      height,
      scaleType,
    );
    const [niceDomainMin, niceDomainMax] = scale.domain();
    const [zeroBaseLineScaleMin, zeroBaseLineScaleMax] =
      zeroBaseLineScale.domain();
    const { min, max } = boundariesForPartialConfig(
      configMinMax!,
      zeroBaseLineScaleMin,
      zeroBaseLineScaleMax,
      niceDomainMin,
      niceDomainMax,
    );

    scale.domain([min, max]);

    return { scale, unit: dataBoundaries.unit };
  }

  return {
    scale: getYScaleForTimeseries(
      { min: Number(scaleMin), max: Number(scaleMax) },
      height,
      scaleType,
    ),
    unit: dataBoundaries.unit,
  };
};

/**
 * Utility method that converts TimeseriesUnit, MinMax Map into an Array
 * holding {min, max, unit}
 *
 * @param mapBoundariesUnit -
 */
const parseMapToArray = (
  mapBoundariesUnit: Map<TimeseriesUnit, MinMax>,
): ScaleMetadata[] => {
  const response: ScaleMetadata[] = [];
  for (const [unit, { min, max }] of mapBoundariesUnit) {
    response.push({ unit, min, max });
  }

  return response;
};

const getDataBoundaries = (
  timeseries: TimeseriesPerVariant,
  seriesMap: WeakMapSeries,
  datapointsMap: WeakMapDatapoints,
): ScaleMetadata[] => {
  const leftMetadata: ScaleMetadata = {};
  const rightMetadata: ScaleMetadata = {};

  const mapBoundariesUnit = timeseries.shapePriority.reduce(
    (boundariesByUnit, variant) => {
      const shapeDomains = getYScaleDomains(
        timeseries[variant as ChartVariant],
        variant as ChartVariant,
        leftMetadata,
        rightMetadata,
        seriesMap,
        datapointsMap,
      );

      shapeDomains.forEach(({ min, max, unit }) => {
        if (boundariesByUnit.has(unit)) {
          const current = boundariesByUnit.get(unit)!;
          const boundaries = {
            min: min ? Math.min(current.min, min) : current.min,
            max: max ? Math.max(current.max, max) : current.max,
          };
          boundariesByUnit.set(unit, boundaries);
        } else {
          boundariesByUnit.set(unit, { min, max } as MinMax);
        }
      });

      return boundariesByUnit;
    },
    new Map<TimeseriesUnit, MinMax>(),
  );

  return parseMapToArray(mapBoundariesUnit);
};

/**
 * Based on configuration assign boundaries to left and/or right axis
 *
 * @param leftConfigMinMax -
 * @param rightConfigMinMax -
 * @param firstUnitBoundaries -
 * @param secondUnitBoundaries -
 */
export const assignBoundariesToYAxes = (
  leftConfigMinMax: Partial<MinMaxConfig> | undefined,
  rightConfigMinMax: Partial<MinMaxConfig> | undefined,
  firstUnitBoundaries: ScaleMetadata | undefined,
  secondUnitBoundaries: ScaleMetadata | undefined,
) => {
  const hasRightAxis = !isUndefined(rightConfigMinMax);
  const hasSecondDomain = !isUndefined(secondUnitBoundaries);

  if (!hasSecondDomain) {
    return hasRightAxis
      ? { rightUnitBoundaries: firstUnitBoundaries }
      : { leftUnitBoundaries: firstUnitBoundaries };
  }

  return {
    leftUnitBoundaries: firstUnitBoundaries,
    rightUnitBoundaries: secondUnitBoundaries,
  };
};

const shouldReturnUserConfig = (
  mainConfig: Partial<MinMaxConfig> | undefined,
): boolean => !isUndefined(mainConfig);

function shouldBuildScale(
  unitBoundaries: ScaleMetadata,
  configMinMax: Partial<MinMaxConfig> | undefined,
) {
  return !isMissingData(unitBoundaries) && shouldReturnUserConfig(configMinMax);
}

function shouldDisplayAxis(
  unitBoundaries: ScaleMetadata,
  defaultDisplay: boolean,
  configMinMax: Partial<MinMaxConfig> | undefined,
) {
  return (
    unitBoundaries &&
    (shouldBuildScale(unitBoundaries, configMinMax) || defaultDisplay)
  );
}

/**
 * Builds 2 scales if needed and assign them to left and/or right axis based in
 * configuration given by the user.
 *
 * @param timeseries -
 * @param config -
 * @param height -
 * @param seriesMap -
 * @param datapointsMap -
 */
export const buildYScales = (
  timeseries: TimeseriesPerVariant,
  config: TimeseriesChartYAxisConfig,
  height: number,
  seriesMap: WeakMapSeries,
  datapointsMap: WeakMapDatapoints,
): YAxisScales => {
  const leftScaleType = config.left?.scale;
  const rightScaleType = config.right?.scale;

  const leftConfigMinMax = getConfigMinMax(config.left);
  const rightConfigMinMax = getConfigMinMax(config.right);

  const [firstUnitBoundaries, secondUnitBoundaries] = getDataBoundaries(
    timeseries,
    seriesMap,
    datapointsMap,
  );

  const { leftUnitBoundaries, rightUnitBoundaries } = assignBoundariesToYAxes(
    leftConfigMinMax,
    rightConfigMinMax,
    firstUnitBoundaries,
    secondUnitBoundaries,
  );

  const displayBothAxisByDefault = !leftConfigMinMax && !rightConfigMinMax;

  const displayLeftAxis = shouldDisplayAxis(
    leftUnitBoundaries as ScaleMetadata,
    displayBothAxisByDefault,
    leftConfigMinMax,
  );
  const displayRightAxis = shouldDisplayAxis(
    rightUnitBoundaries as ScaleMetadata,
    displayBothAxisByDefault,
    rightConfigMinMax,
  );

  const left = displayLeftAxis
    ? buildYScale(
        height,
        leftUnitBoundaries as Required<ScaleMetadata>,
        leftConfigMinMax,
        leftScaleType,
      )
    : undefined;

  const right = displayRightAxis
    ? buildYScale(
        height,
        rightUnitBoundaries as Required<ScaleMetadata>,
        rightConfigMinMax,
        rightScaleType,
      )
    : undefined;

  return {
    left,
    right,
  } as YAxisScales;
};
